item.description:
&lt;h2 id=&#34;cve-2025-53938-bypass-de-autenticação-devido-à-ausência-de-validação-de-sessão-em-múltiplos-endpoints&#34;&gt;CVE-2025-53938: Bypass de Autenticação devido à Ausência de Validação de Sessão em Múltiplos Endpoints
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;Publicação CVE: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-53938&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-53938&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;resumo&#34;&gt;Resumo
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;Uma vulnerabilidade de &lt;b&gt;Bypass de Autenticação&lt;/b&gt; foi identificado no endpoint &lt;code&gt;/dao/verificar_recursos_cargo.php&lt;/code&gt; da aplicação WeGia. Esta vulnerabilidade permite que &lt;b&gt;usuários não autenticados&lt;/b&gt; acessem funcionalidades protegidas do aplicativo e recuperem informações confidenciais enviando solicitações HTTP criadas &lt;b&gt;sem cookies de sessão ou tokens de autenticação&lt;/b&gt;.&lt;/p&gt;
&lt;h2 id=&#34;detalhes&#34;&gt;Detalhes
&lt;/h2&gt;&lt;h3 id=&#34;endpoints-vulneráveis&#34;&gt;Endpoints Vulneráveis:
&lt;/h3&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;/dao/verificar_recursos_cargo.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/exibir_cargo.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/verificar_modulos_visiveis.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/exibir_documento.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/adicionar_documento.php&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/p&gt;

item.content:encoded:
&lt;h2 id=&#34;cve-2025-53938-bypass-de-autenticação-devido-à-ausência-de-validação-de-sessão-em-múltiplos-endpoints&#34;&gt;CVE-2025-53938: Bypass de Autenticação devido à Ausência de Validação de Sessão em Múltiplos Endpoints
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;Publicação CVE: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-53938&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-53938&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;resumo&#34;&gt;Resumo
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;Uma vulnerabilidade de &lt;b&gt;Bypass de Autenticação&lt;/b&gt; foi identificado no endpoint &lt;code&gt;/dao/verificar_recursos_cargo.php&lt;/code&gt; da aplicação WeGia. Esta vulnerabilidade permite que &lt;b&gt;usuários não autenticados&lt;/b&gt; acessem funcionalidades protegidas do aplicativo e recuperem informações confidenciais enviando solicitações HTTP criadas &lt;b&gt;sem cookies de sessão ou tokens de autenticação&lt;/b&gt;.&lt;/p&gt;
&lt;h2 id=&#34;detalhes&#34;&gt;Detalhes
&lt;/h2&gt;&lt;h3 id=&#34;endpoints-vulneráveis&#34;&gt;Endpoints Vulneráveis:
&lt;/h3&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;/dao/verificar_recursos_cargo.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/exibir_cargo.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/verificar_modulos_visiveis.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/exibir_documento.php&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/dao/adicionar_documento.php&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/p&gt;
&lt;h3 id=&#34;autenticação-necessária&#34;&gt;Autenticação Necessária:
&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;❌ Não&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;poc&#34;&gt;PoC
&lt;/h2&gt;&lt;p&gt;&lt;img src=&#34;/p/cve-2025-53938/image.png&#34;
	width=&#34;1058&#34;
	height=&#34;749&#34;
	srcset=&#34;/p/cve-2025-53938/image_hu_e3306e3cf65cbbc2.png 480w, /p/cve-2025-53938/image_hu_50392cb7cd1239e4.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;141&#34;
		data-flex-basis=&#34;339px&#34;

 /&gt;&lt;/p&gt;
&lt;h2 id=&#34;impacto&#34;&gt;Impacto
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;A falta de validação de sessão neste endpoint pode levar a vários riscos de segurança:&lt;/p&gt;
&lt;p style=&#34;text-align: justify;&#34;&gt;
&lt;ul&gt;
&lt;li&gt;&lt;b&gt;Exposição de Dados Não Autorizada:&lt;/b&gt; Usuários não autenticados podem enumerar ou recuperar dados internos confidenciais.&lt;/li&gt;
&lt;li&gt;&lt;b&gt;Escalonamento de Privilégios:&lt;/b&gt; Invasores podem acessar ou inferir informações destinadas apenas a usuários autorizados.&lt;/li&gt;
&lt;li&gt;&lt;b&gt;Divulgação de Informações:&lt;/b&gt; Lógica de negócios e IDs internos (como funções ou permissões de usuário) podem ser vazados.&lt;/li&gt;
&lt;li&gt;&lt;b&gt;Suporte de Reconhecimento:&lt;/b&gt; Facilita o mapeamento de estruturas de backend para ataques mais direcionados.&lt;/li&gt;
&lt;/ul&gt;
&lt;/p&gt;
&lt;h2 id=&#34;referência&#34;&gt;Referência
&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-6p76-7mm4-j5rj&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-6p76-7mm4-j5rj&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;encontrado-por&#34;&gt;Encontrado por:
&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;http://www.linkedin.com/in/marceloqueirozjr&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;&lt;img src=&#34;/assets/contributors/50x50/marcelo50x50.png&#34;



	loading=&#34;lazy&#34;


 /&gt;&lt;/a&gt; &lt;a class=&#34;link&#34; href=&#34;http://www.linkedin.com/in/marceloqueirozjr&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;Marcelo Queiroz&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;colaborador&#34;&gt;Colaborador
&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://www.linkedin.com/in/nmmorette/&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;&lt;img src=&#34;/assets/contributors/50x50/natan50x50.png&#34;



	loading=&#34;lazy&#34;


 /&gt;&lt;/a&gt; &lt;a class=&#34;link&#34; href=&#34;https://www.linkedin.com/in/nmmorette/&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;Natan Maia Morette&lt;/a&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;Por: &lt;a class=&#34;link&#34; href=&#34;https://github.com/Sec-Dojo-Cyber-House/cve-hunters&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;CVE-Hunters&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
