		data-flex-grow=&#34;209&#34;
		data-flex-basis=&#34;502px&#34;

&gt;&lt;/p&gt;

item.content:encoded:
&lt;h2 id=&#34;cve-2025-53527-vulnerabilidade-de-injeção-sql-nos-parâmetros-tipo-e-responsavel-do-endpoint-relatorio_geracaophp&#34;&gt;CVE-2025-53527: Vulnerabilidade de Injeção SQL nos parâmetros &lt;code&gt;tipo&lt;/code&gt; e &lt;code&gt;responsavel&lt;/code&gt; do endpoint &lt;code&gt;relatorio_geracao.php&lt;/code&gt;
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;Publicação CVE: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-53527&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-53527&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;resumo&#34;&gt;Resumo
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;Uma vulnerabilidade de Injeção SQL foi identificada nos parâmetros &lt;code&gt;tipo&lt;/code&gt; e &lt;code&gt;responsavel&lt;/code&gt; do endpoint &lt;code&gt;/controle/relatorio_geracao.php&lt;/code&gt;. Esta vulnerabilidade permite que invasores manipulem consultas SQL e acessem informações confidenciais do banco de dados, como nomes de tabelas e dados sensíveis.&lt;/p&gt;
&lt;h2 id=&#34;detalhes&#34;&gt;Detalhes
&lt;/h2&gt;&lt;p&gt;Endpoint Vulnerável: &lt;code&gt;/controle/relatorio_geracao.php&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;Parâmetros: &lt;code&gt;tipo&lt;/code&gt; e &lt;code&gt;responsavel&lt;/code&gt;&lt;/p&gt;
&lt;h2 id=&#34;poc&#34;&gt;PoC
&lt;/h2&gt;&lt;h3 id=&#34;requisição-normal&#34;&gt;Requisição Normal:
&lt;/h3&gt;&lt;p&gt;&lt;img src=&#34;/p/cve-2025-53527/image.png&#34;
	width=&#34;1772&#34;
	height=&#34;846&#34;
	srcset=&#34;/p/cve-2025-53527/image_hu_4ead4c411acbfc85.png 480w, /p/cve-2025-53527/image_hu_378d044d0498fc9.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;209&#34;
		data-flex-basis=&#34;502px&#34;

 /&gt;&lt;/p&gt;
&lt;h3 id=&#34;sql-injection-no-parâmetro-tipo&#34;&gt;SQL Injection no parâmetro &lt;code&gt;tipo&lt;/code&gt;
&lt;/h3&gt;&lt;h4 id=&#34;payload&#34;&gt;Payload:
&lt;/h4&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt;1
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-fallback&#34; data-lang=&#34;fallback&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;  ;SELECT SLEEP(10)#
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
