	width=&#34;1889&#34;
	height=&#34;997&#34;
	srcset=&#34;/p/cve-2025-7109/image-1_hu_60a60555d7528d3a.png 480w, /p/cve-2025-7109/image-1_hu_1abeeb2b65e62c22.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;189&#34;
