	width=&#34;1909&#34;
	height=&#34;989&#34;
	srcset=&#34;/p/cve-2025-6477/image-1_hu_f09a3ad56b404d14.png 480w, /p/cve-2025-6477/image-1_hu_e0f5609d6ecb5124.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;193&#34;
		data-flex-basis=&#34;463px&#34;

 /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/p/cve-2025-6477/image-2.png&#34;
	width=&#34;1887&#34;
	height=&#34;1005&#34;
	srcset=&#34;/p/cve-2025-6477/image-2_hu_117d198a06d18269.png 480w, /p/cve-2025-6477/image-2_hu_7046a41012ca59a3.png 1024w&#34;
